put('packages/sql-semantics/src/Core/Schema/Definition.php',r'''<?php

declare(strict_types=1);

namespace SqlSemantics\Core\Schema;

use SqlSemantics\Statement\Statement;

/**
 * An ordered definition of database state, expressed entirely as typed SQL values.
 *
 * Names need not resolve yet: CREATE, ALTER, DROP, indexes, views, routines and
 * seed statements retain all their fields, including dialect-specific options.
 * This is a declaration document; it does not execute its commands.
 *
 * @visibility public
 * @example An empty definition
 *     (new \SqlSemantics\Core\Schema\Definition())->toString() // => ''
 */
final class Definition
{
    /** @var list<Statement> Commands in declaration order */
    public readonly array $statements;

    /**
     * Accepts only complete immutable statements, in their supplied order.
     */
    public function __construct(Statement ...$statements)
    {
        $this->statements = array_values($statements);
    }

    /**
     * Replaces the entire declaration sequence without changing this definition.
     */
    public function withStatements(Statement ...$statements): self
    {
        return new self(...$statements);
    }

    /**
     * Appends declarations without changing this definition or its shared values.
     */
    public function append(Statement ...$statements): self
    {
        return new self(...$this->statements, ...array_values($statements));
    }

    /**
     * Writes complete SQL from the values, including statement boundaries.
     */
    public function toString(): string
    {
        return implode("\n", array_map(static fn (Statement $statement): string => rtrim($statement->toString(), " \n\r\t;") . ';', $this->statements));
    }
}
''')
