declare(strict_types=1);

namespace SqlSemantics\Facade;

use SqlSemantics\Core\Analysis\Analyzer;
use SqlSemantics\Core\Ast\DialectParser;
use SqlSemantics\Core\Ast\Identifiers;
use SqlSemantics\Core\Ast\SchemaReader;
use SqlSemantics\Core\Dialect;
use SqlSemantics\Core\Schema;
use SqlSemantics\Core\Schema\Definition;
use SqlSemantics\Statement\Statement;

/**
 * Analyzes database-state definitions into the same typed values as Semantics.
 *
 * Analysis accepts the complete selected language. Catalog binding separately
 * checks whether declarations describe a closed set of known table columns.
 *
 * @visibility public
 * @example Reading a definition without a live database
 *     $semantics = new \SqlSemantics\Facade\SchemaSemantics(\SqlSemantics\Platform\Sqlite\Dialect::Sqlite);
 *     $semantics->analyze('DROP TABLE IF EXISTS t')->toString() // => 'DROP TABLE IF EXISTS t;'
 */
final class SchemaSemantics
{
    private readonly Analyzer $analyzer;
    private readonly DialectParser $parser;
    public readonly string $defaultSchema;

    /**
     * Selects the declaration language, release and unqualified table namespace.
     */
    public function __construct(public readonly Dialect $dialect, ?string $defaultSchema = null, ?string $grammarVersion = null)
    {
        $this->defaultSchema = $defaultSchema ?? $dialect->platform()->defaultSchema();
        $this->parser = new DialectParser($dialect, $grammarVersion);
        $this->analyzer = new Analyzer($dialect, $this->parser->version());
    }

    /**
     * Structures every declaration, without requiring catalog-valid SQL.
     *
     * @throws \SqlSemantics\Core\AnalysisException When SQL is outside the selected language
     */
    public function analyze(string ...$sql): Definition
    {
        return new Definition(...array_map(fn (string $text): Statement => $this->analyzer->analyze($text), array_values($sql)));
    }

    /**
     * Resolves a definition into the closed table snapshot required by Binder.
     *
     * @throws \SqlSemantics\Core\SemanticException When catalog facts conflict or cannot be resolved
     */
    public function bind(Definition $definition): Schema
    {
        return $this->catalog(...array_map(static fn (Statement $statement): string => $statement->toString(), $definition->statements));
    }

    /**
     * Reads CREATE/DROP table declarations directly into a binding snapshot.
     *
     * @throws \SqlSemantics\Core\SemanticException When catalog facts conflict or cannot be resolved
     * @throws \SqlParser\Lexer\LexicalException When SQL contains invalid tokens
     * @throws \SqlParser\Parser\SyntaxException When SQL is outside the selected grammar
     */
    public function catalog(string ...$sql): Schema
    {
        $trees = array_map($this->parser->parse(...), array_values($sql));
        $values = $this->dialect->platform()->values($this->parser->version());
        $tables = (new SchemaReader(new Identifiers($this->dialect), $this->defaultSchema, $values))->read($trees);

        return new Schema($this->dialect, $tables, $this->defaultSchema, $this->parser->version());
    }
}
